<?php
declare(strict_types=1);
final class PCPollRepository {
 public static function member(PDO $p,int $cid,int $uid):bool { $s=$p->prepare('SELECT 1 FROM conversation_members WHERE conversation_id=? AND user_id=? LIMIT 1');$s->execute([$cid,$uid]);return (bool)$s->fetchColumn(); }
 public static function create(PDO $p,int $cid,int $uid,array $d):int { $p->beginTransaction();try{$s=$p->prepare('INSERT INTO polls (conversation_id,creator_id,question,allow_multiple,anonymous,closes_at) VALUES (?,?,?,?,?,?)');$s->execute([$cid,$uid,$d['question'],(int)$d['allow_multiple'],(int)$d['anonymous'],$d['closes_at']]);$id=(int)$p->lastInsertId();$o=$p->prepare('INSERT INTO poll_options (poll_id,option_text,position) VALUES (?,?,?)');foreach($d['options'] as $i=>$v)$o->execute([$id,$v,$i]);$p->commit();return $id;}catch(Throwable $e){if($p->inTransaction())$p->rollBack();throw $e;} }
 public static function get(PDO $p,int $id,int $uid):?array { $s=$p->prepare('SELECT p.* FROM polls p JOIN conversation_members c ON c.conversation_id=p.conversation_id AND c.user_id=? WHERE p.id=? LIMIT 1');$s->execute([$uid,$id]);$poll=$s->fetch();if(!$poll)return null;$o=$p->prepare('SELECT o.id,o.option_text,o.position,COUNT(v.user_id) votes,MAX(CASE WHEN v.user_id=? THEN 1 ELSE 0 END) voted_by_me FROM poll_options o LEFT JOIN poll_votes v ON v.option_id=o.id WHERE o.poll_id=? GROUP BY o.id,o.option_text,o.position ORDER BY o.position,o.id');$o->execute([$uid,$id]);return ['id'=>(string)$poll['id'],'conversation_id'=>(string)$poll['conversation_id'],'creator_id'=>(string)$poll['creator_id'],'question'=>$poll['question'],'allow_multiple'=>(bool)$poll['allow_multiple'],'anonymous'=>(bool)$poll['anonymous'],'closes_at'=>$poll['closes_at'],'created_at'=>$poll['created_at'],'options'=>array_map(static fn(array $x):array=>['id'=>(string)$x['id'],'text'=>$x['option_text'],'votes'=>(int)$x['votes'],'voted_by_me'=>(bool)$x['voted_by_me']],$o->fetchAll())]; }
 public static function vote(PDO $p,int $id,int $uid,array $ids):array { $p->beginTransaction();try{$s=$p->prepare('SELECT p.allow_multiple,p.closes_at FROM polls p JOIN conversation_members c ON c.conversation_id=p.conversation_id AND c.user_id=? WHERE p.id=? FOR UPDATE');$s->execute([$uid,$id]);$poll=$s->fetch();if(!$poll){$p->rollBack();return ['status'=>404,'body'=>['ok'=>false,'error'=>'poll_not_found']];}if($poll['closes_at']!==null && strtotime((string)$poll['closes_at'].' UTC')<=time()){$p->rollBack();return ['status'=>409,'body'=>['ok'=>false,'error'=>'poll_closed']];}if(!(bool)$poll['allow_multiple']&&count($ids)!==1){$p->rollBack();return ['status'=>422,'body'=>['ok'=>false,'error'=>'choose_exactly_one_option']];}$marks=implode(',',array_fill(0,count($ids),'?'));$c=$p->prepare('SELECT COUNT(*) FROM poll_options WHERE poll_id=? AND id IN ('.$marks.')');$c->execute(array_merge([$id],$ids));if((int)$c->fetchColumn()!==count($ids)){$p->rollBack();return ['status'=>422,'body'=>['ok'=>false,'error'=>'invalid_poll_options']];}$p->prepare('DELETE FROM poll_votes WHERE poll_id=? AND user_id=?')->execute([$id,$uid]);$i=$p->prepare('INSERT INTO poll_votes (poll_id,option_id,user_id) VALUES (?,?,?)');foreach($ids as $oid)$i->execute([$id,$oid,$uid]);$p->commit();return ['status'=>200,'body'=>['ok'=>true,'poll_id'=>(string)$id,'voted'=>true]];}catch(Throwable $e){if($p->inTransaction())$p->rollBack();throw $e;} }
}
